{
  "name": "Retro Neon Terminal",
  "description": "A high-performance, aesthetically pleasing retro-web personal hub inspired by early 2000s and developer-centric aesthetics. Features a glassmorphic terminal, real-time Gemini-powered assistant, and interactive widgets.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Terminal, Command, Cpu, Globe, MessageSquare, ExternalLink, Github, Twitter, Mail, Activity, Lock, Settings } from 'lucide-react';

// --- Types ---
interface LogEntry {
  type: 'cmd' | 'res' | 'info';
  content: string;
  timestamp: string;
}

// --- Components ---
const SidebarItem: React.FC<{ icon: React.ReactNode; label: string; active?: boolean; onClick: () => void }> = ({ icon, label, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center gap-3 px-4 py-3 text-sm transition-all duration-200 border-l-2 ${
      active 
        ? 'bg-green-500/10 border-green-500 text-green-400' 
        : 'border-transparent text-zinc-500 hover:bg-zinc-800 hover:text-zinc-300'
    }`}
  >
    {icon}
    <span className="font-medium tracking-tight">{label}</span>
  </button>
);

const App: React.FC = () => {
  const [logs, setLogs] = useState<LogEntry[]>([
    { type: 'info', content: 'SYSTEM BOOT SUCCESSFUL', timestamp: '00:00:01' },
    { type: 'info', content: 'INITIALIZING USER_SHELL v1.0.4', timestamp: '00:00:02' },
    { type: 'info', content: 'WELCOME TO DIMDEN_STYLE_TERMINAL. TYPE "help" TO BEGIN.', timestamp: '00:00:03' },
  ]);
  const [inputValue, setInputValue] = useState('');
  const [activeTab, setActiveTab] = useState('terminal');
  const [isAiThinking, setIsAiThinking] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs]);

  const handleCommand = async (cmd: string) => {
    const timestamp = new Date().toLocaleTimeString([], { hour12: false });
    const trimmedCmd = cmd.trim().toLowerCase();

    setLogs(prev => [...prev, { type: 'cmd', content: cmd, timestamp }]);

    if (trimmedCmd === 'clear') {
      setLogs([{ type: 'info', content: 'LOGS CLEARED.', timestamp }]);
      return;
    }

    if (trimmedCmd === 'help') {
      setLogs(prev => [...prev, { 
        type: 'res', 
        content: 'AVAILABLE COMMANDS: clear, help, whoami, ping, contact, ai [query]', 
        timestamp 
      }]);
      return;
    }

    if (trimmedCmd === 'whoami') {
      setLogs(prev => [...prev, { 
        type: 'res', 
        content: 'USER_ID: ANONYMOUS\nROLE: WEB_EXPLORER\nLOCATION: GLOBAL_NET', 
        timestamp 
      }]);
      return;
    }

    if (trimmedCmd === 'ping') {
      setLogs(prev => [...prev, { 
        type: 'res', 
        content: 'PONG (32ms)', 
        timestamp 
      }]);
      return;
    }

    if (trimmedCmd.startsWith('ai ')) {
      const query = cmd.substring(3);
      await askAI(query, timestamp);
      return;
    }

    setLogs(prev => [...prev, { 
      type: 'res', 
      content: `COMMAND NOT FOUND: ${cmd}. TRY "help".`, 
      timestamp 
    }]);
  };

  const askAI = async (prompt: string, timestamp: string) => {
    setIsAiThinking(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          systemInstruction: "You are a terminal assistant. Keep your responses concise, technical, and formatted for a monospace CLI environment. Use caps for headings. Do not use markdown bolding."
        }
      });
      const text = response.text || "NO_RESPONSE_RECEIVED";
      setLogs(prev => [...prev, { type: 'res', content: `AI RESPONSE:\n${text}`, timestamp }]);
    } catch (err) {
      setLogs(prev => [...prev, { type: 'res', content: `ERROR: AI_SUBSYSTEM_OFFLINE. ${err}`, timestamp }]);
    } finally {
      setIsAiThinking(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue) return;
    handleCommand(inputValue);
    setInputValue('');
  };

  const focusInput = () => {
    inputRef.current?.focus();
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#050505] selection:bg-green-500/30 selection:text-green-300">
      {/* Sidebar - Desktop Only Left Nav */}
      <aside className="w-full md:w-64 border-b md:border-b-0 md:border-r border-zinc-900 bg-[#080808] z-20">
        <div className="p-6 flex items-center gap-2">
          <div className="w-3 h-3 rounded-full bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]"></div>
          <div className="w-3 h-3 rounded-full bg-yellow-500 shadow-[0_0_8px_rgba(234,179,8,0.5)]"></div>
          <div className="w-3 h-3 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]"></div>
          <h1 className="ml-2 font-bold text-sm tracking-widest text-zinc-400">HUB_OS v1.0</h1>
        </div>

        <nav className="mt-4">
          <SidebarItem icon={<Terminal size={18}/>} label="TERMINAL" active={activeTab === 'terminal'} onClick={() => setActiveTab('terminal')} />
          <SidebarItem icon={<Globe size={18}/>} label="WEB_LINKS" active={activeTab === 'web'} onClick={() => setActiveTab('web')} />
          <SidebarItem icon={<Cpu size={18}/>} label="SYSTEM_LOGS" active={activeTab === 'logs'} onClick={() => setActiveTab('logs')} />
          <SidebarItem icon={<MessageSquare size={18}/>} label="AI_CHANNEL" active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} />
        </nav>

        <div className="mt-12 px-6">
          <p className="text-[10px] text-zinc-600 uppercase font-bold tracking-widest mb-4">Network Connectivity</p>
          <div className="flex gap-4">
            <a href="#" className="text-zinc-600 hover:text-green-500 transition-colors"><Github size={18} /></a>
            <a href="#" className="text-zinc-600 hover:text-green-500 transition-colors"><Twitter size={18} /></a>
            <a href="#" className="text-zinc-600 hover:text-green-500 transition-colors"><Mail size={18} /></a>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col relative overflow-hidden" onClick={focusInput}>

        {/* Dynamic Header */}
        <header className="h-14 border-b border-zinc-900 flex items-center justify-between px-6 bg-[#050505]/80 backdrop-blur-md z-10">
          <div className="flex items-center gap-4">
            <span className="text-xs text-zinc-500 font-bold uppercase tracking-tighter">Status:</span>
            <span className="flex items-center gap-2 text-xs text-green-500 font-bold glow-text animate-pulse">
              <Activity size={12} />
              ONLINE
            </span>
          </div>
          <div className="flex items-center gap-6">
            <div className="hidden sm:flex items-center gap-2 text-[10px] text-zinc-600">
               <Lock size={10} />
               ENCRYPTED_AES_256
            </div>
            <button className="text-zinc-500 hover:text-white transition-colors">
              <Settings size={16} />
            </button>
          </div>
        </header>

        {/* Dynamic Viewport */}
        <div className="flex-1 p-4 md:p-8 overflow-hidden flex flex-col">

          {/* Terminal View */}
          {activeTab === 'terminal' && (
            <div className="flex-1 flex flex-col bg-[#080808] border border-zinc-800 rounded-lg overflow-hidden shadow-2xl">
              <div className="p-2 bg-zinc-900/50 border-b border-zinc-800 flex justify-between items-center px-4">
                <span className="text-[10px] text-zinc-500 font-mono tracking-widest">root@system:~</span>
                <div className="flex gap-1.5">
                  <div className="w-2 h-2 rounded-full bg-zinc-700"></div>
                  <div className="w-2 h-2 rounded-full bg-zinc-700"></div>
                </div>
              </div>

              <div 
                ref={scrollRef}
                className="flex-1 overflow-y-auto p-4 font-mono text-sm space-y-2 custom-scrollbar"
              >
                {logs.map((log, i) => (
                  <div key={i} className="animate-in fade-in slide-in-from-left-2 duration-300">
                    <div className="flex gap-3 opacity-80">
                      <span className="text-zinc-600 text-[10px] shrink-0 mt-0.5">[{log.timestamp}]</span>
                      {log.type === 'cmd' ? (
                        <span className="text-green-400 flex gap-2">
                          <span className="text-zinc-400">$</span> {log.content}
                        </span>
                      ) : log.type === 'res' ? (
                        <span className="text-zinc-300 whitespace-pre-wrap leading-relaxed">{log.content}</span>
                      ) : (
                        <span className="text-blue-400 font-bold uppercase tracking-widest text-[11px]">{log.content}</span>
                      )}
                    </div>
                  </div>
                ))}
                {isAiThinking && (
                  <div className="flex gap-3 animate-pulse">
                    <span className="text-zinc-600 text-[10px] shrink-0">AI_CORE:</span>
                    <span className="text-green-500">THINKING_IN_PROGRESS...</span>
                  </div>
                )}
              </div>

              <form onSubmit={handleSubmit} className="p-4 bg-black/40 border-t border-zinc-800 flex items-center gap-3">
                <span className="text-green-500 font-bold">$</span>
                <input 
                  ref={inputRef}
                  type="text"
                  autoFocus
                  className="bg-transparent border-none outline-none flex-1 text-green-400 font-mono placeholder:text-zinc-800"
                  placeholder="enter command..."
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                />
              </form>
            </div>
          )}

          {/* Links View */}
          {activeTab === 'web' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 animate-in zoom-in-95 duration-300">
              {[
                { title: "Github Repository", desc: "Core engine sources", link: "#", color: "text-purple-400" },
                { title: "Developer Blog", desc: "Thoughts on web tech", link: "#", color: "text-blue-400" },
                { title: "Project: X-Net", desc: "Decentralized experiments", link: "#", color: "text-orange-400" },
                { title: "API Documentation", desc: "Access the system", link: "#", color: "text-pink-400" },
                { title: "Community Matrix", desc: "Real-time chat links", link: "#", color: "text-cyan-400" },
                { title: "Legal & Privacy", desc: "How we treat data", link: "#", color: "text-emerald-400" },
              ].map((item, i) => (
                <a 
                  key={i} 
                  href={item.link}
                  className="group p-6 bg-[#080808] border border-zinc-900 rounded-xl hover:border-green-500/50 hover:bg-[#0c0c0c] transition-all duration-300"
                >
                  <div className="flex justify-between items-start mb-4">
                    <span className={`text-[10px] font-bold uppercase tracking-[0.2em] ${item.color}`}>RESOURCE_{i + 1}</span>
                    <ExternalLink size={14} className="text-zinc-700 group-hover:text-green-500 transition-colors" />
                  </div>
                  <h3 className="text-lg font-bold text-zinc-100 mb-2">{item.title}</h3>
                  <p className="text-sm text-zinc-500 leading-relaxed">{item.desc}</p>
                </a>
              ))}
            </div>
          )}

          {/* AI View */}
          {activeTab === 'ai' && (
            <div className="flex-1 flex flex-col items-center justify-center space-y-8 animate-in fade-in duration-700">
              <div className="relative">
                <div className="absolute inset-0 bg-green-500 rounded-full blur-[80px] opacity-10 animate-pulse"></div>
                <div className="w-32 h-32 border-4 border-zinc-800 rounded-full flex items-center justify-center bg-[#080808] relative z-10 shadow-[0_0_40px_rgba(0,0,0,0.5)]">
                  <Cpu size={48} className="text-green-500" />
                </div>
              </div>
              <div className="text-center space-y-2">
                <h2 className="text-2xl font-bold tracking-tight text-white">GEMINI_CORE_LINKED</h2>
                <p className="text-zinc-500 max-w-md mx-auto">
                  Enhanced neural assistant is ready. Use the terminal with "ai [your query]" or click below to start a direct session.
                </p>
              </div>
              <button 
                onClick={() => { setActiveTab('terminal'); setInputValue('ai hello, introduce yourself'); }}
                className="px-8 py-3 bg-green-500/10 border border-green-500 text-green-500 font-bold uppercase tracking-widest text-xs hover:bg-green-500 hover:text-black transition-all rounded-full shadow-[0_0_20px_rgba(34,197,94,0.1)]"
              >
                INITIALIZE_SESSION
              </button>
            </div>
          )}

          {/* Stats View */}
          {activeTab === 'logs' && (
             <div className="bg-[#080808] border border-zinc-900 rounded-xl p-8 space-y-8 animate-in slide-in-from-bottom-4 duration-500">
                <div className="flex items-center gap-4 border-b border-zinc-900 pb-6">
                  <div className="p-3 bg-zinc-900 rounded-lg">
                    <Activity className="text-green-500" />
                  </div>
                  <div>
                    <h3 className="text-lg font-bold text-white">SYSTEM_DIAGNOSTICS</h3>
                    <p className="text-xs text-zinc-500 font-mono">ID: 48F-99-XA1</p>
                  </div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                  {[
                    { label: "CPU_LOAD", val: "12%", color: "text-green-400" },
                    { label: "MEM_USAGE", val: "4.2GB", color: "text-blue-400" },
                    { label: "NET_TRAFFIC", val: "840KB/S", color: "text-purple-400" },
                    { label: "UPTIME", val: "148:12:04", color: "text-orange-400" }
                  ].map((stat, i) => (
                    <div key={i} className="space-y-1">
                      <p className="text-[10px] text-zinc-600 font-bold uppercase tracking-widest">{stat.label}</p>
                      <p className={`text-xl font-bold font-mono ${stat.color}`}>{stat.val}</p>
                    </div>
                  ))}
                </div>

                <div className="space-y-3 pt-4">
                  <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest mb-4">Live Event Log</p>
                  {[
                    "INBOUND_CONN_ESTABLISHED [192.168.1.1]",
                    "CACHE_FLUSH_TRIGGERED [AUTO]",
                    "KEY_ROTATION_SUCCESSFUL [AES_256]",
                    "SUBSYSTEM_SYNC_COMPLETE"
                  ].map((msg, i) => (
                    <div key={i} className="flex gap-4 text-xs font-mono text-zinc-400">
                      <span className="text-zinc-700">00:0{i + 4}:22</span>
                      <span className="text-zinc-500">|</span>
                      <span>{msg}</span>
                    </div>
                  ))}
                </div>
             </div>
          )}
        </div>

        {/* Footer info line */}
        <footer className="h-10 bg-zinc-900/20 border-t border-zinc-900 px-6 flex items-center justify-between text-[10px] text-zinc-600 font-mono tracking-widest">
          <div className="flex gap-6">
             <span>LOC: 52.3676° N, 4.9041° E</span>
             <span className="hidden sm:inline">TZ: UTC+1</span>
          </div>
          <div className="flex gap-4">
             <span className="text-green-900/50">MEM: 12.8%</span>
             <span className="animate-pulse">● SIGNAL: STRONG</span>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Terminal, Command, Cpu, Globe, MessageSquare, ExternalLink, Github, Twitter, Mail, Activity, Lock, Settings, User, Code, Heart, Layers } from 'lucide-react';

// --- Types ---
interface LogEntry {
  type: 'cmd' | 'res' | 'info';
  content: string;
  timestamp: string;
}

// --- Components ---
const SidebarItem: React.FC<{ icon: React.ReactNode; label: string; active?: boolean; onClick: () => void }> = ({ icon, label, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center gap-3 px-4 py-3 text-sm transition-all duration-200 border-l-2 ${
      active 
        ? 'bg-green-500/10 border-green-500 text-green-400' 
        : 'border-transparent text-zinc-500 hover:bg-zinc-800 hover:text-zinc-300'
    }`}
  >
    {icon}
    <span className="font-medium tracking-tight">{label}</span>
  </button>
);

const App: React.FC = () => {
  const [logs, setLogs] = useState<LogEntry[]>([
    { type: 'info', content: 'SYSTEM BOOT SUCCESSFUL', timestamp: '00:00:01' },
    { type: 'info', content: 'INITIALIZING PERSONAL_SPACE v2.1.0', timestamp: '00:00:02' },
    { type: 'info', content: 'WELCOME. TYPE "whoami" TO LEARN MORE OR "help" FOR COMMANDS.', timestamp: '00:00:03' },
  ]);
  const [inputValue, setInputValue] = useState('');
  const [activeTab, setActiveTab] = useState('terminal');
  const [isAiThinking, setIsAiThinking] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs]);

  const handleCommand = async (cmd: string) => {
    const timestamp = new Date().toLocaleTimeString([], { hour12: false });
    const trimmedCmd = cmd.trim().toLowerCase();

    setLogs(prev => [...prev, { type: 'cmd', content: cmd, timestamp }]);

    if (trimmedCmd === 'clear') {
      setLogs([{ type: 'info', content: 'LOGS CLEARED.', timestamp }]);
      return;
    }

    if (trimmedCmd === 'help') {
      setLogs(prev => [...prev, { 
        type: 'res', 
        content: 'AVAILABLE COMMANDS:\nwhoami  - Display profile info\nclear   - Wipe terminal buffer\nsocials - List social media links\nprojects- Recent work highlights\nskills  - Technical proficiency\nai      - Chat with my neural assistant', 
        timestamp 
      }]);
      return;
    }

    if (trimmedCmd === 'whoami') {
      setLogs(prev => [...prev, { 
        type: 'res', 
        content: 'NAME: [YOUR NAME]\nROLE: FULL STACK ENGINEER / CREATIVE TECH\nFOCUS: HIGH-PERFORMANCE WEB & AI INTERFACES\nBIO: CRAFTING DIGITAL EXPERIENCES AT THE INTERSECTION OF RETRO AESTHETICS AND MODERN PERFORMANCE.', 
        timestamp 
      }]);
      return;
    }

    if (trimmedCmd === 'socials') {
        setLogs(prev => [...prev, { 
          type: 'res', 
          content: 'GITHUB: github.com/[yourhandle]\nTWITTER: x.com/[yourhandle]\nLINKEDIN: linkedin.com/in/[yourhandle]\nEMAIL: hello@yourdomain.dev', 
          timestamp 
        }]);
        return;
      }

    if (trimmedCmd.startsWith('ai ')) {
      const query = cmd.substring(3);
      await askAI(query, timestamp);
      return;
    }

    setLogs(prev => [...prev, { 
      type: 'res', 
      content: `COMMAND NOT FOUND: ${cmd}. TRY "help" OR "whoami".`, 
      timestamp 
    }]);
  };

  const askAI = async (prompt: string, timestamp: string) => {
    setIsAiThinking(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          systemInstruction: "You are the personal assistant for this website's owner. You are knowledgeable about their tech stack (React, TypeScript, Tailwind, AI integration) and their retro-terminal aesthetic. Keep responses professional yet slightly cyperpunk in tone."
        }
      });
      const text = response.text || "NO_RESPONSE_RECEIVED";
      setLogs(prev => [...prev, { type: 'res', content: `AI RESPONSE:\n${text}`, timestamp }]);
    } catch (err) {
      setLogs(prev => [...prev, { type: 'res', content: `ERROR: AI_SUBSYSTEM_OFFLINE.`, timestamp }]);
    } finally {
      setIsAiThinking(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue) return;
    handleCommand(inputValue);
    setInputValue('');
  };

  const focusInput = () => {
    inputRef.current?.focus();
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#050505] selection:bg-green-500/30 selection:text-green-300">
      <aside className="w-full md:w-64 border-b md:border-b-0 md:border-r border-zinc-900 bg-[#080808] z-20">
        <div className="p-6 flex items-center gap-2">
          <div className="flex gap-1">
            <div className="w-2.5 h-2.5 rounded-full bg-[#ff5f56]"></div>
            <div className="w-2.5 h-2.5 rounded-full bg-[#ffbd2e]"></div>
            <div className="w-2.5 h-2.5 rounded-full bg-[#27c93f]"></div>
          </div>
          <h1 className="ml-3 font-bold text-xs tracking-[0.2em] text-zinc-500">USER@ROOT</h1>
        </div>

        <nav className="mt-4">
          <SidebarItem icon={<User size={18}/>} label="PROFILE" active={activeTab === 'terminal'} onClick={() => setActiveTab('terminal')} />
          <SidebarItem icon={<Globe size={18}/>} label="SOCIALS" active={activeTab === 'web'} onClick={() => setActiveTab('web')} />
          <SidebarItem icon={<Code size={18}/>} label="STACK" active={activeTab === 'logs'} onClick={() => setActiveTab('logs')} />
          <SidebarItem icon={<MessageSquare size={18}/>} label="AI_ASSISTANT" active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} />
        </nav>

        <div className="mt-auto p-6 border-t border-zinc-900/50">
          <p className="text-[10px] text-zinc-600 uppercase font-bold tracking-widest mb-4">Quick Connect</p>
          <div className="flex gap-4">
            <a href="https://github.com" target="_blank" className="text-zinc-600 hover:text-green-500 transition-colors"><Github size={18} /></a>
            <a href="https://twitter.com" target="_blank" className="text-zinc-600 hover:text-green-500 transition-colors"><Twitter size={18} /></a>
            <a href="mailto:hello@example.com" className="text-zinc-600 hover:text-green-500 transition-colors"><Mail size={18} /></a>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative overflow-hidden" onClick={focusInput}>
        <header className="h-14 border-b border-zinc-900 flex items-center justify-between px-6 bg-[#050505]/80 backdrop-blur-md z-10">
          <div className="flex items-center gap-4">
            <span className="text-xs text-zinc-500 font-bold uppercase tracking-tighter">Status:</span>
            <span className="flex items-center gap-2 text-xs text-green-500 font-bold glow-text">
              <Activity size={12} className="animate-pulse" />
              LIVE_SYSTEM
            </span>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden md:block h-2 w-32 bg-zinc-900 rounded-full overflow-hidden">
                <div className="h-full bg-green-500/50 w-[78%]"></div>
             </div>
             <span className="text-[10px] text-zinc-600 font-mono">ENCRYPT_v3</span>
          </div>
        </header>

        <div className="flex-1 p-4 md:p-8 overflow-hidden flex flex-col">
          {activeTab === 'terminal' && (
