const API_KEY = '7611726a978f141829e74d150242138b';

interface Track {
  name: string;
  artist: string;
  nowPlaying: boolean;
}

interface Particle {
  id: number;
  x: number;
  y: number;
  angle: number;
  velocity: number;
}

