        setTrack({
          name: lastTrack.name,
          artist: typeof lastTrack.artist === 'object' ? lastTrack.artist['#text'] : lastTrack.artist,
          nowPlaying: lastTrack['@attr']?.nowplaying === 'true',
          url: lastTrack.url
        });
      }
    } catch (err) {
      console.error("Last.fm fetch failed:", err);
    }
  };

  useEffect(() => {
    fetchLastFm();
    const interval = setInterval(fetchLastFm, 15000); // Poll every 15s for more reactive "now playing"
    return () => clearInterval(interval);
  }, []);

  return (
