import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Github, Sparkles, Activity, 
  Cloud, Monitor, Heart, Zap, Music, User,
  Cpu, HardDrive, Terminal,
  Layers, Zap as Power, ExternalLink, ShieldCheck,
  AlertCircle, Play, History
} from 'lucide-react';

// Using your provided Last.fm details
const LASTFM_USER = 'IvanPurr'; 
const API_KEY = '7611726a978f141829e74d150242138b';

interface Track {
  name: string;
  artist: string;
  nowPlaying: boolean;
  url: string;
}

interface Particle {
  id: number;
  x: number;
  y: number;
  angle: number;
  velocity: number;
}

const App: React.FC = () => {
  const [track, setTrack] = useState<Track | null>(null);
  const [hasInteracted, setHasInteracted] = useState(false);
  const [particles, setParticles] = useState<Particle[]>([]);
  const particleIdCounter = useRef(0);

  const playSound = useCallback((type: 'hover' | 'click') => {
    if (!hasInteracted) return;
    try {
      const audio = new Audio();
      if (type === 'hover') {
        audio.src = 'https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3';
        audio.volume = 0.05;
      } else {
        audio.src = 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3';
        audio.volume = 0.1;
      }
      audio.play().catch(() => {});
    } catch (e) {}
  }, [hasInteracted]);

  const createParticles = (e: React.MouseEvent) => {
    const centerX = e.clientX;
    const centerY = e.clientY;
    const newParticles: Particle[] = [];
    for (let i = 0; i < 12; i++) {
      newParticles.push({
        id: particleIdCounter.current++,
        x: centerX,
        y: centerY,
        angle: (Math.PI * 2 / 12) * i + (Math.random() * 0.5),
        velocity: 2 + Math.random() * 4
      });
    }
    setParticles(prev => [...prev, ...newParticles]);
    setTimeout(() => {
      setParticles(prev => prev.filter(p => !newParticles.find(np => np.id === p.id)));
    }, 1000);
  };

  const handleLinkClick = (e: React.MouseEvent) => {
    playSound('click');
    createParticles(e);
  };

  useEffect(() => {
    const handleFirstInteraction = () => {
      setHasInteracted(true);
      window.removeEventListener('click', handleFirstInteraction);
    };
    window.addEventListener('click', handleFirstInteraction);
    return () => window.removeEventListener('click', handleFirstInteraction);
  }, []);

  const fetchLastFm = async () => {
    try {
      // Fetching specifically recent tracks for the user
      const url = `https://ws.audioscrobbler.com/2.0/?method=user.getrecenttracks&user=${LASTFM_USER}&api_key=${API_KEY}&format=json&limit=1`;
      const resp = await fetch(url);
      if (!resp.ok) return;
      const data = await resp.json();

      if (data?.recenttracks?.track && data.recenttracks.track.length > 0) {
        const lastTrack = data.recenttracks.track[0];
        setTrack({
          name: lastTrack.name,
          artist: lastTrack.artist['#text'] || lastTrack.artist.name || "Unknown Artist",
          nowPlaying: lastTrack['@attr']?.nowplaying === 'true',
          url: lastTrack.url
        });
