            <div className="p-3 md:p-5">
              <nav className="w-full flex flex-col gap-2">
                {[
                  { icon: <Github size={16} />, label: 'GitHub', url: 'https://github.com/KitsuyaDev' },
                  { icon: <Monitor size={16} />, label: 'Twitch', url: 'https://twitch.tv/kitsuyatv' },
