                ].map((link, idx) => (
                  <a key={idx} href={link.url} target="_blank" className="sidebar-link group !p-2 rounded hover:bg-pink-400/5" onClick={handleLinkClick} onMouseEnter={() => playSound('hover')}>
                    <div className="flex items-center gap-3">
