import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Github, Sparkles, Activity, 
  Cloud, Monitor, Heart, Zap, Music, User,
  Cpu, HardDrive, Terminal,
  ExternalLink, ShieldCheck,
  AlertCircle, Disc, Clock, Play, Trophy,
  List, Layout, Info, Eye, Flame
} from 'lucide-react';

// Using your provided "Stats spice" Last.fm API Key
const LASTFM_USER = 'IvanPurr'; 
const LASTFM_API_KEY = '52f25787af57e73404ef01ba7a400fac';

interface Track {
  name: string;
  artist: string;
  album: string;
  image: string;
  nowPlaying: boolean;
  url: string;
  lastSeen?: string;
}

interface Particle {
  id: number;
  x: number;
  y: number;
  angle: number;
  velocity: number;
  color?: string;
  isFlame?: boolean;
}

const App: React.FC = () => {
  const [track, setTrack] = useState<Track | null>(null);
  const [hasInteracted, setHasInteracted] = useState(false);
  const [particles, setParticles] = useState<Particle[]>([]);
  const [isOverload, setIsOverload] = useState(false);
  const [headerClicks, setHeaderClicks] = useState(0);
  const [showHud, setShowHud] = useState(false);
  const [tailCount, setTailCount] = useState(1);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  // Oneko State
  const [onekoPos, setOnekoPos] = useState({ x: 100, y: 100 });
  const [onekoState, setOnekoState] = useState<'idle' | 'walking' | 'sleeping'>('idle');
  const [onekoFrame, setOnekoFrame] = useState(0);

  const particleIdCounter = useRef(0);
  const konamiIndex = useRef(0);
  const kitsuyaIndex = useRef(0);
  const onekoRef = useRef({ x: 100, y: 100 });

  const konamiCode = ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight', 'b', 'a'];
  const kitsuyaCode = ['k', 'i', 't', 's', 'u', 'y', 'a'];

  const playSound = useCallback((type: 'hover' | 'click' | 'xp' | 'secret' | 'glitch' | 'fire' | 'meow') => {
    if (!hasInteracted) return;
    try {
      const audio = new Audio();
      const sources = {
        hover: 'https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3',
        click: 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3',
        xp: 'https://www.myinstants.com/media/sounds/levelup.mp3',
        secret: 'https://assets.mixkit.co/active_storage/sfx/2534/2534-preview.mp3',
        glitch: 'https://assets.mixkit.co/active_storage/sfx/2556/2556-preview.mp3',
        fire: 'https://assets.mixkit.co/active_storage/sfx/2436/2436-preview.mp3',
        meow: 'https://assets.mixkit.co/active_storage/sfx/1360/1360-preview.mp3'
      };
      audio.src = sources[type as keyof typeof sources];
      audio.volume = type === 'hover' ? 0.05 : 0.15;
      audio.play().catch(() => {});
    } catch (e) {}
  }, [hasInteracted]);

  const createParticles = (e: { clientX: number, clientY: number }, count = 12, color = '#ffb7c5', isFlame = false) => {
    const centerX = e.clientX;
    const centerY = e.clientY;
    const newParticles: Particle[] = [];
    const actualCount = isOverload ? count * 2 : count;

    for (let i = 0; i < actualCount; i++) {
      newParticles.push({
        id: particleIdCounter.current++,
        x: centerX,
        y: centerY,
        angle: (Math.PI * 2 / actualCount) * i + (Math.random() * 0.5),
        velocity: isFlame ? 1 + Math.random() * 2 : 2 + Math.random() * 4,
        color: isOverload ? '#60a5fa' : color,
        isFlame
      });
    }
    setParticles(prev => [...prev, ...newParticles]);
    setTimeout(() => {
      setParticles(prev => prev.filter(p => !newParticles.find(np => np.id === p.id)));
    }, isFlame ? 500 : 1000);
  };

  const handleLinkClick = (e: React.MouseEvent) => {
    playSound('click');
    createParticles({ clientX: e.clientX, clientY: e.clientY }, 8, isOverload ? '#60a5fa' : '#ffb7c5');
  };

  // Oneko logic
  useEffect(() => {
    const interval = setInterval(() => {
      const diffX = mousePos.x - onekoRef.current.x;
      const diffY = mousePos.y - onekoRef.current.y;
      const distance = Math.sqrt(diffX * diffX + diffY * diffY);

      if (distance > 32) {
        setOnekoState('walking');
        const speed = isOverload ? 12 : 6;
        const vx = (diffX / distance) * speed;
        const vy = (diffY / distance) * speed;
        onekoRef.current = { x: onekoRef.current.x + vx, y: onekoRef.current.y + vy };
        setOnekoPos({ ...onekoRef.current });
      } else {
        setOnekoState(Math.random() > 0.99 ? 'sleeping' : 'idle');
      }
      setOnekoFrame(f => (f + 1) % 4);
    }, 100);
    return () => clearInterval(interval);
  }, [mousePos, isOverload]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setMousePos({ x: e.clientX, y: e.clientY });
      if (showHud && Math.random() > 0.85) {
        createParticles({ clientX: e.clientX, clientY: e.clientY }, 1, '#60a5fa', true);
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [showHud, isOverload]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();

      const targetKonamiKey = konamiCode[konamiIndex.current].toLowerCase();
      if (key === targetKonamiKey || e.key === konamiCode[konamiIndex.current]) {
        konamiIndex.current++;
        if (konamiIndex.current === konamiCode.length) {
          setIsOverload(true);
          playSound('secret');
          setTimeout(() => setIsOverload(false), 12000);
          konamiIndex.current = 0;
        }
      } else {
        konamiIndex.current = 0;
      }

      if (key === kitsuyaCode[kitsuyaIndex.current]) {
        kitsuyaIndex.current++;
        if (kitsuyaIndex.current === kitsuyaCode.length) {
          setShowHud(true);
          playSound('glitch');
          setTimeout(() => setShowHud(false), 15000);
          kitsuyaIndex.current = 0;
        }
      } else {
        kitsuyaIndex.current = 0;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [playSound]);

  useEffect(() => {
    const handleFirstInteraction = () => {
      setHasInteracted(true);
      window.removeEventListener('click', handleFirstInteraction);
    };
    window.addEventListener('click', handleFirstInteraction);
    return () => window.removeEventListener('click', handleFirstInteraction);
  }, []);

  const fetchLastFm = async () => {
    try {
      const response = await fetch(
        `https://ws.audioscrobbler.com/2.0/?method=user.getrecenttracks&user=${LASTFM_USER}&api_key=${LASTFM_API_KEY}&format=json&limit=1`
      );
      const data = await response.json();
      if (data?.recenttracks?.track?.length > 0) {
        const latest = data.recenttracks.track[0];
        setTrack({
          name: latest.name,
          artist: latest.artist['#text'],
          album: latest.album['#text'],
          image: latest.image[2]['#text'] || '',
          nowPlaying: latest['@attr']?.nowplaying === 'true',
          url: latest.url,
          lastSeen: latest.date?.['#text'] || 'Recently'
        });
      }
    } catch (error) {}
  };

  useEffect(() => {
    fetchLastFm();
    const interval = setInterval(fetchLastFm, 15000);
    return () => clearInterval(interval);
  }, []);

  const handleHeaderClick = (e: React.MouseEvent) => {
    setHeaderClicks(prev => {
      const next = prev + 1;
      if (next > 0 && next % 10 === 0) {
        playSound('xp');
        createParticles({ clientX: e.clientX, clientY: e.clientY }, 30, '#4ade80');
      } else {
        playSound('click');
        createParticles({ clientX: e.clientX, clientY: e.clientY }, 5);
      }
      return next;
    });
  };

  const handlePfpClick = (e: React.MouseEvent) => {
    setTailCount(prev => (prev >= 9 ? 1 : prev + 1));
    playSound('fire');
    createParticles({ clientX: e.clientX, clientY: e.clientY }, 10 + tailCount * 2, '#60a5fa');
  };

  const handleOnekoClick = (e: React.MouseEvent) => {
    playSound('meow');
    createParticles({ clientX: e.clientX, clientY: e.clientY }, 15, '#60a5fa', true);
  };

  return (
    <div className={`max-w-[1400px] mx-auto space-y-6 relative z-10 py-4 px-2 md:px-6 transition-all duration-1000 ${isOverload ? 'bg-blue-950/40' : ''}`}>
      {/* Oneko Sprite */}
      <div 
        className={`fixed w-8 h-8 pointer-events-auto cursor-pointer z-[150] transition-transform duration-100 ${isOverload ? 'drop-shadow-[0_0_8px_#60a5fa]' : ''}`}
        style={{ 
          left: onekoPos.x - 16, 
