  nowPlaying: boolean;
  url: string;
  lastSeen?: string;
}

interface Particle {
  id: number;
  x: number;
  y: number;
  angle: number;
  velocity: number;
  color?: string;
  isFlame?: boolean;
}

const App: React.FC = () => {
  const [track, setTrack] = useState<Track | null>(null);
