import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Github, Sparkles, Activity, 
  Cloud, Monitor, Heart, Zap, Music, User,
  Cpu, Terminal, ExternalLink, ShieldCheck,
  AlertCircle, Disc, Clock, Play, Trophy,
  List, Layout, Coffee, Settings2, Sun, Moon,
  Cpu as CpuIcon, Eye
} from 'lucide-react';

// Using your provided "Stats spice" Last.fm API Key
const LASTFM_USER = 'IvanPurr'; 
const LASTFM_API_KEY = '52f25787af57e73404ef01ba7a400fac';

interface Track {
  name: string;
  artist: string;
  album: string;
  image: string;
  nowPlaying: boolean;
  url: string;
  lastSeen?: string;
}

interface Particle {
  id: number;
  x: number;
  y: number;
  angle: number;
  velocity: number;
  color?: string;
}

const App: React.FC = () => {
  const [track, setTrack] = useState<Track | null>(null);
  const [hasInteracted, setHasInteracted] = useState(false);
  const [particles, setParticles] = useState<Particle[]>([]);
  const [isOverload, setIsOverload] = useState(false);
  const [rainbowMode, setRainbowMode] = useState(false);
  const [headerClicks, setHeaderClicks] = useState(0);
  const [liveMem, setLiveMem] = useState(24.50);
  const [performanceMode, setPerformanceMode] = useState(false);
  const [lightMode, setLightMode] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const particleIdCounter = useRef(0);
  const konamiIndex = useRef(0);
  const konamiCode = ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight', 'b', 'a'];

  const rainbowInput = useRef("");

  const togglePerformance = () => {
    // performanceMode = true means FX are DISABLED
    setPerformanceMode(!performanceMode);
    document.body.classList.toggle('performance-mode');
    playSound('click');
  };

  const toggleLightMode = () => {
    setLightMode(!lightMode);
    document.body.classList.toggle('light-mode');
    // Using the original working sparkle sound for luminescence
    playSound('lumine'); 
  };

  const playSound = useCallback((type: 'hover' | 'click' | 'xp' | 'secret' | 'rainbow' | 'lumine') => {
    if (!hasInteracted) return;
    try {
      const audio = new Audio();
      const sources = {
        hover: 'https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3',
        click: 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3',
        lumine: 'https://assets.mixkit.co/active_storage/sfx/2019/2019-preview.mp3', // The working sparkle/spark sound
        xp: 'https://www.myinstants.com/media/sounds/minecraft_xp_sound_effect.mp3', // Reliable Minecraft XP source
        secret: 'https://assets.mixkit.co/active_storage/sfx/2534/2534-preview.mp3',
        rainbow: 'https://www.myinstants.com/media/sounds/shooting-stars-meme.mp3'
      };
      audio.src = sources[type as keyof typeof sources];
      audio.volume = type === 'hover' ? 0.04 : (type === 'rainbow' ? 0.2 : 0.3);
      audio.play().catch(() => {});
    } catch (e) {}
  }, [hasInteracted]);

  const createParticles = (e: React.MouseEvent | { clientX: number, clientY: number }, count = 12, color = '#ffb7c5') => {
    if (performanceMode) return;
    const centerX = e.clientX;
    const centerY = e.clientY;
    const newParticles: Particle[] = [];
    for (let i = 0; i < count; i++) {
      newParticles.push({
        id: particleIdCounter.current++,
        x: centerX,
        y: centerY,
        angle: (Math.PI * 2 / count) * i + (Math.random() * 0.5),
        velocity: 2 + Math.random() * 4,
        color: rainbowMode ? `hsl(${Math.random() * 360}, 100%, 70%)` : color
      });
    }
    setParticles(prev => [...prev, ...newParticles]);
    setTimeout(() => {
      setParticles(prev => prev.filter(p => !newParticles.find(np => np.id === p.id)));
    }, 1000);
  };

  const handleLinkClick = (e: React.MouseEvent) => {
    playSound('click');
    createParticles(e);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();

      // Rainbow trigger
      rainbowInput.current += key;
      if (rainbowInput.current.endsWith("rainbow")) {
        setRainbowMode(prev => !prev);
        playSound('rainbow');
        rainbowInput.current = "";
      } else if (rainbowInput.current.length > 20) {
        rainbowInput.current = rainbowInput.current.slice(-10);
      }

      // Konami
      const targetKey = konamiCode[konamiIndex.current].toLowerCase();
      if (key === targetKey || e.key === konamiCode[konamiIndex.current]) {
        konamiIndex.current++;
        if (konamiIndex.current === konamiCode.length) {
          setIsOverload(true);
          playSound('secret');
          setTimeout(() => setIsOverload(false), 5000);
          konamiIndex.current = 0;
        }
      } else {
        konamiIndex.current = 0;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [playSound]);

  useEffect(() => {
    document.body.classList.toggle('rainbow-mode', rainbowMode);

