          className={`dimden-panel p-3 text-pink-300 hover:text-white flex items-center gap-2 group transition-all rounded-full ${showSettings ? 'border-pink-500 shadow-[0_0_15px_rgba(255,183,197,0.4)]' : ''}`}
        >
