               <span className={`terminal-font text-xl sm:text-2xl drop-shadow-[0_0_10px_rgba(255,255,255,0.1)] transition-all duration-700 ${isPanic ? 'text-red-500 font-bold underline' : (lightMode ? 'text-pink-700' : 'text-pink-100')}`}>
