              <div className={`terminal-font text-lg sm:text-xl leading-relaxed space-y-5 relative z-10 ${lightMode ? 'text-pink-900' : 'text-pink-50'} ${rainbowMode ? 'text-white' : ''}`}>
                {isPanic ? (
