               <span className="text-white/20 font-bold uppercase tracking-[0.4em] mb-2 text-[8px]">ALLOC_RAM</span>
               <span className={`terminal-font text-2xl sm:text-3xl transition-all duration-700 ${isPanic ? 'text-red-500' : 'text-pink-100'}`}>
                {liveMem.toFixed(2)}GB <span className="text-white/10 text-sm">/ 28GB</span>
               </span>
             </div>
             <div className="flex flex-col items-center">
               <span className="text-white/20 font-bold uppercase tracking-[0.4em] mb-2 text-[8px]">SYNC_TPS</span>
               <span className={`terminal-font text-4xl sm:text-5xl drop-shadow-[0_0_15px_rgba(74,222,128,0.2)] ${isPanic ? 'text-red-600' : 'text-green-400'}`}>
                {isPanic ? (Math.random() * 5).toFixed(2) : '20.00'}
               </span>
             </div>
          </div>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-12 gap-8 md:gap-10">
        <aside className="md:col-span-3 space-y-8 order-2 md:order-1">
          {/* Identity Panel */}
          <div className="dimden-panel p-0 overflow-hidden group border-white/5">
            <div className="bg-white/[0.02] p-3 border-b border-white/5 flex items-center justify-between">
              <h3 className="pixel-title text-[7px] opacity-30 uppercase tracking-widest">Profile</h3>
              <User size={12} className="text-white/10" />
            </div>
            <div className="p-5 space-y-2">
                {[
                  { label: 'Name', value: 'Kit' },
                  { label: 'Age', value: '20' },
                  { label: 'Pronouns', value: 'They/Them' },
                  { label: 'Loc', value: 'GMT' }
                ].map((item, idx) => (
                  <div key={idx} className="flex justify-between items-center py-2 border-b border-white/[0.03] last:border-0 hover:bg-white/[0.02] transition-all px-2 rounded">
                    <span className="terminal-font text-white/30 text-base uppercase tracking-widest">{item.label}</span>
                    <span className="terminal-font text-xl text-pink-100">{isPanic ? '???' : item.value}</span>
                  </div>
                ))}
            </div>
          </div>

          <div className="dimden-panel p-0 overflow-hidden group border-white/5">
            <div className="bg-white/[0.02] p-3 border-b border-white/5 flex items-center justify-between">
              <h3 className="pixel-title text-[7px] opacity-30 uppercase tracking-widest">Connect</h3>
              <List size={12} className="text-white/10" />
            </div>
            <nav className="flex flex-col p-2 gap-1">
              {[
                { label: 'GitHub', icon: Github, href: 'https://github.com/KitsuyaDev' },
                { label: 'Twitch', icon: Monitor, href: 'https://twitch.tv/kitsuyatv' },
                { label: 'BlueSky', icon: Cloud, href: 'https://bsky.app/profile/kitsuya.space' }
              ].map((link, idx) => (
                <a key={idx} href={link.href} target="_blank" className="sidebar-link group/link !text-xl !py-3 px-4 rounded-lg flex items-center gap-4" onClick={handleLinkClick} onMouseEnter={() => playSound('hover')}>
                  <link.icon size={18} className="text-white/20 group-hover/link:text-pink-400 transition-all" />
                  <span>{link.label}</span>
                </a>
              ))}
            </nav>
          </div>

          {/* Minimal Listening Status */}
          <div className="dimden-panel p-0 overflow-hidden group border-white/5">
             <div className="bg-white/[0.02] p-3 border-b border-white/5 flex items-center justify-between">
               <h3 className="pixel-title text-[7px] opacity-30 uppercase tracking-widest flex items-center gap-2">
                 <Music size={12} className="text-pink-400/60" /> Listening Status
               </h3>
               {track?.nowPlaying && <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse shadow-[0_0_10px_rgba(74,222,128,0.5)]" />}
             </div>
             <div className="p-4">
               {track ? (
                 <a href={track.url} target="_blank" className="flex items-center gap-4 group/track">
                    <div className="w-12 h-12 rounded-lg border border-white/10 overflow-hidden shrink-0 shadow-lg group-hover/track:border-pink-500/40 transition-all">
                      <img src={track.image || ''} className="w-full h-full object-cover" alt="Art" />
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="terminal-font text-lg leading-none truncate text-white">{track.name}</p>
                      <p className="terminal-font text-sm text-white/40 truncate uppercase tracking-tight mt-1">{track.artist}</p>
                    </div>
                 </a>
               ) : (
                 <div className="text-center py-4 opacity-10 terminal-font text-sm uppercase tracking-widest">Waiting for signal</div>
               )}
             </div>
          </div>
        </aside>

        <main className="md:col-span-6 space-y-8 order-1 md:order-2">
          {/* About Me Section - Tightened & Content Restored */}
          <section className="dimden-panel p-0 overflow-hidden group border-white/5">
            <div className="bg-white/[0.02] p-4 border-b border-white/5 flex items-center justify-between">
              <h3 className="pixel-title text-[8px] opacity-40 uppercase tracking-[0.3em] flex items-center gap-2">
                <Sparkles size={14} className="text-pink-300" /> About_Me.txt
              </h3>
              <Terminal size={14} className="text-white/10" />
            </div>
            <div className="p-5 sm:p-6 relative overflow-hidden flex flex-col justify-start">
              <div className="absolute -bottom-2 -right-2 opacity-[0.02] pointer-events-none group-hover:opacity-[0.05] transition-opacity duration-1000">
                <Terminal size={120} className="text-white" />
              </div>
              <div className={`terminal-font text-xl sm:text-2xl space-y-3 relative z-10 ${lightMode ? 'text-pink-900' : 'text-pink-50'}`}>
                {isPanic ? (
                  <div className="space-y-4 text-red-500">
                    <p className="text-3xl font-bold">CORE_MEMORY_CORRUPT</p>
                    <p className="text-xl opacity-50">0x82883311</p>
                  </div>
                ) : (
                  <>
                    <p className="text-3xl sm:text-4xl text-pink-400 font-bold tracking-tight">hihi :3 im kit</p>
                    <p className="opacity-90">
                      i’ve been doing minecraft dev stuff for around 7–8 years, mostly focused on performance and systems. i mainly work with fabric and neoforge.
                    </p>
                    <p className="opacity-90">
                      i spend a lot of time fixing tps issues, digging through crash logs, and removing things that don’t need to exist. if something is slow or broken, i’ll usually keep poking at it until i understand why.
                    </p>
                    <p className="opacity-90">
                      i’ve worked on some projects i’m really proud of, but unfortunately a lot of the cool ones are under nda, so i can’t say much about them. i also make modpacks and help optimize higher-end networks.
                    </p>
                  </>
                )}
              </div>
            </div>
          </section>

          {/* Recommended Host Section - Pulled higher */}
          <section className="dimden-panel p-0 overflow-hidden group/hosting border-pink-500/10 hover:border-pink-500/30 relative">
            <div className="bg-pink-500/[0.02] p-4 border-b border-pink-500/10 flex items-center justify-between">
               <h2 className="pixel-title text-[8px] uppercase tracking-[0.4em] text-pink-300/40 flex items-center gap-2">
                 <Star size={16} className="text-pink-300 fill-pink-300/10" /> Recommended Host
               </h2>
               <ShieldCheck size={18} className="text-pink-400/20" />
            </div>
            <div className="p-8">
              <div className="flex flex-col sm:flex-row items-center gap-8 mb-8">
                <div className="w-28 h-28 bg-pink-950/20 border-2 border-pink-500/10 p-3 shadow-2xl relative shrink-0 group-hover/hosting:scale-105 transition-all duration-700">
                  <img src="https://avatars.githubusercontent.com/u/132858781?s=200&v=4" className="w-full h-full object-cover" alt="Pyro" />
                  <div className="absolute inset-0 ring-4 ring-pink-500/5" />
                </div>
                <div className="flex-1 text-center sm:text-left">
                  <h3 className="terminal-font text-4xl uppercase tracking-[0.2em] mb-2 text-white">Pyro</h3>
                  <p className="terminal-font text-xl text-pink-200/60 leading-tight">
                    Superior performance and hardware stability for modded environments and high-traffic networks.
                  </p>
                </div>
              </div>

              <div className="dimden-panel border-pink-500/20 bg-pink-500/[0.03] p-6 mb-8 relative rounded-xl backdrop-blur-3xl">
                <div className="flex gap-5 items-start">
                   <ThumbsUp size={28} className="text-pink-400 shrink-0 mt-1 opacity-60" />
                   <p className="terminal-font text-2xl italic leading-relaxed text-white/90">
                    "Honestly the only host I trust for my own projects. Their hardware handles heavily modded environments like a dream. If you want something that actually stays up, this is it."
                   </p>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row items-center justify-between gap-8">
                <a href="https://pyro.host/?a=41" target="_blank" className="w-full sm:w-auto inline-flex dimden-panel px-16 py-4 items-center justify-center gap-4 terminal-font text-3xl text-white bg-pink-500/10 border-pink-500/40 hover:bg-pink-500/20 hover:shadow-[0_0_40px_rgba(255,183,197,0.2)] transition-all group/btn rounded-lg" onClick={handleLinkClick}>
                  <span>Visit</span>
                  <ExternalLink size={20} className="group-hover/btn:translate-x-1 group-hover/btn:-translate-y-1 transition-transform" />
                </a>

                <div className="flex items-center gap-4 text-white/20 terminal-font text-base uppercase tracking-[0.2em] border-l border-white/5 pl-8 h-10">
                  <Shield size={20} className="opacity-30" />
                  <span>Trust_Verified</span>
                </div>
              </div>

              <div className="mt-8 p-4 border-t border-white/5 flex items-start gap-5 text-white/30 terminal-font text-sm uppercase tracking-widest leading-relaxed">
                <Info size={18} className="shrink-0 mt-0.5 opacity-20" />
