        </main>

        <aside className="md:col-span-3 space-y-8 order-3">
          <div className="dimden-panel p-0 overflow-hidden group border-white/5">
             <div className="bg-white/[0.02] p-3 border-b border-white/5 flex items-center justify-between">
               <h3 className="pixel-title text-[7px] opacity-30 uppercase tracking-widest">Heartbeat</h3>
               <Activity size={14} className="text-white/10" />
             </div>
             <div className="p-5 terminal-font space-y-6">
                <div className="flex justify-between items-end border-b border-white/5 pb-3">
                  <span className="text-white/20 text-sm tracking-[0.2em] uppercase">UPTIME</span> 
                  <span className={`text-2xl ${isPanic ? 'text-red-500' : 'text-pink-100'}`}>99.9%</span>
                </div>
                <div className="flex gap-1.5 h-10 items-end">
                   {[40, 70, 30, 90, 50, 80, 20, 60, 45, 75, 55, 85].map((h, i) => (
                     <div key={i} className="w-full transition-all duration-1000 rounded-t-sm bg-pink-500/10 group-hover:bg-pink-500/40" style={{height: `${h}%`}} />
                   ))}
                </div>
             </div>
          </div>

          <div className="dimden-panel p-0 overflow-hidden group border-white/5">
             <div className="bg-white/[0.02] p-3 border-b border-white/5 flex items-center justify-between">
               <h3 className="pixel-title text-[7px] opacity-30 uppercase tracking-widest">Hardware</h3>
               <Cpu size={14} className="text-white/10" />
             </div>
             <div className="p-5 terminal-font space-y-2 relative z-10">
                {[
                  { label: 'CPU', value: 'Epyc 7543P' },
