            <div className="cursor-pointer select-none" onClick={handleHeaderClick}>
              <h1 className="pixel-title text-2xl sm:text-3xl md:text-4xl mb-3 transition-all tracking-tight uppercase flex items-center justify-center sm:justify-start gap-4">
                {isPanic ? 'SYS_CRITICAL' : 'KITSUYA.SPACE'}
                {headerClicks >= 50 && !isPanic && <Trophy size={20} className="text-yellow-400 animate-bounce" />}
              </h1>
              <div className="flex items-center justify-center sm:justify-start gap-4">
                <div className="relative flex items-center justify-center">
                  <span className={`w-3 h-3 rounded-full ${isPanic ? 'bg-red-500 animate-pulse' : track?.nowPlaying ? 'bg-green-400' : 'bg-pink-400'}`} />
                  {!performanceMode && <span className={`absolute w-6 h-6 rounded-full animate-ping opacity-30 ${isPanic ? 'bg-red-500' : track?.nowPlaying ? 'bg-green-400' : 'bg-pink-400'}`} />}
                </div>
                <p className={`terminal-font text-xl sm:text-2xl opacity-60 uppercase tracking-widest ${lightMode ? 'text-pink-600' : 'text-pink-100'}`}>
                  {isPanic ? 'LOGGING_FAIL_0x0' : '~ root@kitsuya: /dev/minecraft'}
                </p>
              </div>
            </div>
          </div>

          <div className="flex gap-10 sm:gap-16 md:border-l border-white/5 md:pl-12 lg:pl-16 relative z-10">
             <div className="flex flex-col items-center">
               <span className="text-white/20 font-bold uppercase tracking-[0.4em] mb-2 text-[8px]">ALLOC_RAM</span>
               <span className={`terminal-font text-2xl sm:text-3xl transition-all duration-700 ${isPanic ? 'text-red-500' : 'text-pink-100'}`}>
                {liveMem.toFixed(2)}GB <span className="text-white/10 text-sm">/ 28GB</span>
               </span>
             </div>
             <div className="flex flex-col items-center">
               <span className="text-white/20 font-bold uppercase tracking-[0.4em] mb-2 text-[8px]">SYNC_TPS</span>
