    e.stopPropagation();
    playSound('parry');
    createParticles(e.clientX, e.clientY, 20, '#00ffff', 'parry');
    setFires(prev => {
      const remaining = prev.filter(f => f.id !== id);
      if (remaining.length === 0) {
        setIsBreach(false);
