import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Github, Sparkles, Activity, 
  Cloud, Monitor, Heart, Zap, Music, User,
  Cpu, Terminal, ExternalLink, ShieldCheck,
  AlertCircle, Disc, Clock, Play, Trophy,
  List, Layout, Coffee, Settings2, Sun, Moon,
  Cpu as CpuIcon, ShieldAlert, ShoppingCart,
  Server, Info, Shield, ThumbsUp, Star,
  History, Radio, Link as LinkIcon, Flame, X
} from 'lucide-react';

const LASTFM_USER = 'IvanPurr'; 
const LASTFM_API_KEY = '52f25787af57e73404ef01ba7a400fac';

interface Track {
  name: string;
  artist: string;
  album: string;
  image: string;
  nowPlaying: boolean;
  url: string;
  lastSeen?: string;
}

interface Particle {
  id: number;
  x: number;
  y: number;
  angle: number;
  velocity: number;
  color?: string;
  type?: 'spark' | 'fire' | 'parry';
}

interface FireEntity {
  id: number;
  x: number;
  y: number;
  size: number;
}

const App: React.FC = () => {
  const [track, setTrack] = useState<Track | null>(null);
  const [hasInteracted, setHasInteracted] = useState(false);
  const [particles, setParticles] = useState<Particle[]>([]);
  const [isBreach, setIsBreach] = useState(false);
  const [fires, setFires] = useState<FireEntity[]>([]);
  const [rainbowMode, setRainbowMode] = useState(false);
  const [headerClicks, setHeaderClicks] = useState(0);
  const [liveMem, setLiveMem] = useState(24.50);
  const [performanceMode, setPerformanceMode] = useState(false);
  const [lightMode, setLightMode] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const particleIdCounter = useRef(0);
  const fireIdCounter = useRef(0);
  const konamiIndex = useRef(0);
  const konamiCode = ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight', 'b', 'a'];
  const rainbowInput = useRef("");
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Added missing toggleLightMode function to handle theme switching
  const toggleLightMode = () => {
    setLightMode(prev => !prev);
    if (!hasInteracted) setHasInteracted(true);
  };

  const playSound = useCallback((type: 'hover' | 'click' | 'xp' | 'breach' | 'parry' | 'rainbow') => {
    if (!hasInteracted) return;
    try {
      const audio = new Audio();
      const sources = {
        hover: 'https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3',
        click: 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3',
        xp: 'https://www.myinstants.com/media/sounds/levelup.mp3', 
        breach: 'https://files.catbox.moe/0v2u0y.mp3', // ULTRACHURCH clip
        parry: 'https://www.myinstants.com/media/sounds/ultrakill-parry.mp3',
        rainbow: 'https://www.myinstants.com/media/sounds/shooting-stars-meme.mp3'
      };
      audio.src = sources[type as keyof typeof sources];
      audio.volume = type === 'hover' ? 0.04 : (type === 'breach' ? 0.15 : (type === 'parry' ? 0.3 : 0.4));

      if (type === 'breach') {
        if (audioRef.current) audioRef.current.pause();
        audioRef.current = audio;
        audio.loop = true;
      }

      audio.play().catch(() => {});
    } catch (e) {}
  }, [hasInteracted]);

  const createParticles = (x: number, y: number, count = 12, color = '#ffb7c5', type: 'spark' | 'parry' = 'spark') => {
    if (performanceMode) return;
    const newParticles: Particle[] = [];
    for (let i = 0; i < count; i++) {
      newParticles.push({
        id: particleIdCounter.current++,
        x,
        y,
        angle: (Math.PI * 2 / count) * i + (Math.random() * 0.5),
        velocity: type === 'parry' ? 8 + Math.random() * 10 : 2 + Math.random() * 4,
        color: rainbowMode ? `hsl(${Math.random() * 360}, 100%, 70%)` : color,
        type
      });
    }
    setParticles(prev => [...prev, ...newParticles]);
    setTimeout(() => {
      setParticles(prev => prev.filter(p => !newParticles.find(np => np.id === p.id)));
    }, 1000);
  };

  const handleGlobalClick = (e: React.MouseEvent) => {
    if (!hasInteracted) setHasInteracted(true);
    if (isBreach) return; // Handled by fire targets
    playSound('click');
    createParticles(e.clientX, e.clientY);
  };

  const spawnFires = () => {
    const newFires: FireEntity[] = [];
    for (let i = 0; i < 8; i++) {
      newFires.push({
        id: fireIdCounter.current++,
        x: 10 + Math.random() * 80,
        y: 10 + Math.random() * 80,
        size: 40 + Math.random() * 60
      });
    }
    setFires(newFires);
  };

  const parryFire = (id: number, e: React.MouseEvent) => {
    e.stopPropagation();
    playSound('parry');
    createParticles(e.clientX, e.clientY, 20, '#00ffff', 'parry');
    setFires(prev => {
      const remaining = prev.filter(f => f.id !== id);
      if (remaining.length === 0) {
        setIsBreach(false);
        if (audioRef.current) {
          audioRef.current.pause();
          audioRef.current = null;
