  const [isMusicPlaying, setIsMusicPlaying] = useState(false);

  const particleIdCounter = useRef(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const playSound = useCallback((type: 'hover' | 'click' | 'xp' | 'parry' | 'rainbow') => {
    if (!hasInteracted) return;
    try {
      const audio = new Audio();
      const sources = {
        hover: 'https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3',
        click: 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3',
        xp: 'https://www.myinstants.com/media/sounds/levelup.mp3', 
        parry: 'https://www.myinstants.com/media/sounds/ultrakill-parry.mp3',
        rainbow: 'https://www.myinstants.com/media/sounds/shooting-stars-meme.mp3'
      };
      audio.src = sources[type] || sources.click;
      audio.volume = type === 'hover' ? 0.04 : (type === 'parry' ? 0.3 : 0.4);
      audio.play().catch(() => {});
    } catch (e) {}
  }, [hasInteracted]);

  const toggleMusic = () => {
    if (!audioRef.current) {
      audioRef.current = new Audio('https://files.catbox.moe/0v2u0y.mp3');
      audioRef.current.loop = true;
      audioRef.current.volume = 0.15;
    }

    if (isMusicPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play().catch(() => {});
    }
    setIsMusicPlaying(!isMusicPlaying);
    if (!hasInteracted) setHasInteracted(true);
  };

  const createParticles = (x: number, y: number, count = 8, color = '#ffb7c5', size = 4) => {
    if (performanceMode) return;
    const newParticles: Particle[] = [];
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const force = 2 + Math.random() * 4;
      newParticles.push({
        id: particleIdCounter.current++,
        x,
        y,
        vx: Math.cos(angle) * force,
        vy: Math.sin(angle) * force,
        color: rainbowMode ? `hsl(${Math.random() * 360}, 100%, 70%)` : color,
        size: Math.random() * size + 2,
        life: 1.0
      });
    }
    setParticles(prev => [...prev, ...newParticles]);
  };

  // Particle Update Loop
  useEffect(() => {
    if (particles.length === 0) return;
    const frame = requestAnimationFrame(() => {
      setParticles(prev => prev
        .map(p => ({
          ...p,
          x: p.x + p.vx,
          y: p.y + p.vy,
          vy: p.vy + 0.1, // Gravity
          life: p.life - 0.02
