    if (nextClicks === 10) {
      playSound('xp');
      addSecret('xp_egg');
      createParticles(e.clientX, e.clientY, 60, '#4ade80', 6);
    } else if (nextClicks < 10) {
      playSound('click');
      createParticles(e.clientX, e.clientY, 8, isUltrakillMode ? '#ef4444' : '#ffb7c5');
    }
  };

  const styleRank = (() => {
    const count = foundSecrets.length;
