            </button>
            {rainbowMode && (
              <button onClick={() => setRainbowMode(false)} className="w-full text-left p-2 hover:bg-red-500/20 rounded terminal-font flex justify-between items-center text-red-400">
                <span>Disable Rainbow</span>
                <Power size={12} />
              </button>
            )}
          </div>
        )}
      </div>

      <footer className={`py-20 text-center terminal-font text-2xl tracking-[0.6em] uppercase hover:text-red-500 transition-all duration-1000 ${isUltrakillMode ? 'text-red-950/40' : (lightMode ? 'text-pink-900/10' : 'text-white/5')}`}>
        ~ 2026 - {isUltrakillMode || styleRank === 'SSS' ? 'mankind is dead' : 'kit\'s corner'} ~
      </footer>
    </div>
  );
};

