              <h3 className="pixel-title text-[7px] opacity-40 uppercase tracking-widest">{isUltrakillMode ? 'ACCESS_NODES' : 'Links'}</h3>
              <LinkIcon size={12} className="text-black/20 dark:text-white/10" />
