import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Github, Sparkles, Activity, 
  Cloud, Monitor, User,
  Cpu, Terminal, ExternalLink, ShieldCheck,
  Trophy, Layout, Coffee, Settings2, Power,
  ShieldAlert, Star, History, Radio, Link as LinkIcon,
  Info, Heart
} from 'lucide-react';

const LASTFM_USER = 'IvanPurr'; 
const LASTFM_API_KEY = '52f25787af57e73404ef01ba7a400fac';

interface Track {
  name: string;
  artist: string;
  album: string;
  image: string;
  nowPlaying: boolean;
  url: string;
}

interface Particle {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  color: string;
  size: number;
  life: number;
  isSparkle?: boolean;
}

const App: React.FC = () => {
  const [track, setTrack] = useState<Track | null>(null);
  const [hasInteracted, setHasInteracted] = useState(false);
  const [particles, setParticles] = useState<Particle[]>([]);
  const [headerClicks, setHeaderClicks] = useState(0);
  const [foundSecrets, setFoundSecrets] = useState<string[]>([]);
  const [performanceMode, setPerformanceMode] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [konamiProgress, setKonamiProgress] = useState<string[]>([]);
  const [isUltrakillMode, setIsUltrakillMode] = useState(false);

  const particleIdCounter = useRef(0);
  const lastMousePos = useRef({ x: 0, y: 0 });

  const createParticles = useCallback((x: number, y: number, count = 8, color = '#ffb7c5', size = 4, isSparkle = false) => {
    if (performanceMode) return;
    const newParticles: Particle[] = [];
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const force = isSparkle ? Math.random() * 1.8 + 0.6 : 2 + Math.random() * 6;
      newParticles.push({
        id: particleIdCounter.current++,
        x,
        y,
        vx: Math.cos(angle) * force,
        vy: isSparkle ? Math.sin(angle) * force : Math.sin(angle) * force - 2,
        color,
        size: isSparkle ? Math.random() * 2 + 1 : Math.random() * size + 2,
        life: 1.0,
        isSparkle
      });
    }
    setParticles(prev => [...prev, ...newParticles]);
  }, [performanceMode]);

  const playSound = useCallback((type: 'hover' | 'click' | 'xp' | 'glitch') => {
    if (!hasInteracted) return;
    try {
      const audio = new Audio();
      const sources = {
        hover: 'https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3',
        click: 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3',
        xp: 'https://www.myinstants.com/media/sounds/levelup.mp3', 
        glitch: 'https://assets.mixkit.co/active_storage/sfx/2658/2658-preview.mp3'
      };
      audio.src = (sources as any)[type] || sources.click;
      audio.volume = type === 'hover' ? 0.04 : 0.25;
      audio.play().catch(() => {});
    } catch (e) {}
  }, [hasInteracted]);

  const addSecret = useCallback((id: string) => {
    if (!foundSecrets.includes(id)) {
      setFoundSecrets(prev => [...prev, id]);
    }
  }, [foundSecrets]);

  useEffect(() => {
    if (performanceMode) return;
    const handleMouseMove = (e: MouseEvent) => {
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      if (Math.random() > 0.65) {
        const color = isUltrakillMode ? '#ef4444' : (Math.random() > 0.5 ? '#ffffff' : '#ffb7c5');
        createParticles(e.clientX, e.clientY, 1, color, 1, true);
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [createParticles, isUltrakillMode, performanceMode]);

  useEffect(() => {
    const code = ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight', 'b', 'a'];
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!hasInteracted) setHasInteracted(true);
      const key = e.key.toLowerCase();
      const expectedKey = code[konamiProgress.length].toLowerCase();

      if (key === expectedKey) {
        const next = [...konamiProgress, key];
        if (next.length === code.length) {
          addSecret('konami');
          setIsUltrakillMode(true);
          setKonamiProgress([]);
          createParticles(window.innerWidth / 2, window.innerHeight / 2, 120, '#ef4444', 10);
        } else {
          setKonamiProgress(next);
        }
      } else {
        setKonamiProgress(key === code[0].toLowerCase() ? [key] : []);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [konamiProgress, addSecret, hasInteracted, createParticles]);

  useEffect(() => {
    if (particles.length === 0) return;
    const frame = requestAnimationFrame(() => {
      setParticles(prev => prev
        .map(p => ({
          ...p,
          x: p.x + p.vx,
          y: p.y + p.vy,
          vy: p.isSparkle ? p.vy + 0.01 : p.vy + 0.15,
          life: p.isSparkle ? p.life - 0.015 : p.life - 0.015
        }))
        .filter(p => p.life > 0)
      );
    });
    return () => cancelAnimationFrame(frame);
  }, [particles]);

  const handleGlobalClick = (e: React.MouseEvent) => {
    if (!hasInteracted) setHasInteracted(true);
    playSound('click');
    const color = isUltrakillMode ? '#ef4444' : (Math.random() > 0.5 ? '#ffffff' : '#ffb7c5');
    createParticles(e.clientX, e.clientY, 15, color);
  };

  const handleHeaderClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!hasInteracted) setHasInteracted(true);
    const nextClicks = headerClicks + 1;
    setHeaderClicks(nextClicks);
    if (nextClicks === 10) {
      playSound('xp');
      addSecret('xp_egg');
      createParticles(e.clientX, e.clientY, 80, '#4ade80', 8);
    } else {
      playSound('click');
      createParticles(e.clientX, e.clientY, 12, isUltrakillMode ? '#ef4444' : '#ffb7c5');
    }
  };

  useEffect(() => {
    const fetchTrack = async () => {
      try {
        const response = await fetch(`https://ws.audioscrobbler.com/2.0/?method=user.getrecenttracks&user=${LASTFM_USER}&api_key=${LASTFM_API_KEY}&format=json&limit=1`);
        const data = await response.json();
        const latest = data?.recenttracks?.track?.[0];
        if (latest) {
          setTrack({
            name: latest.name,
            artist: latest.artist['#text'],
            album: latest.album['#text'],
            image: latest.image[3]['#text'],
            nowPlaying: latest['@attr']?.nowplaying === 'true',
            url: latest.url
          });
        }
      } catch (e) {}
    };
    fetchTrack();
    const interval = setInterval(fetchTrack, 30000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div 
      id="root-container" 
      onMouseDown={handleGlobalClick}
      className={`max-w-[1400px] mx-auto space-y-6 md:space-y-8 relative z-10 py-4 px-3 md:px-6 transition-all duration-700 bg-transparent ${isUltrakillMode ? 'text-red-500' : 'text-white'}`}
    >

      {isUltrakillMode && (
        <style dangerouslySetInnerHTML={{ __html: `
          #grid { background-image: linear-gradient(rgba(239, 68, 68, 0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(239, 68, 68, 0.1) 1px, transparent 1px) !important; }
          #mouse-glow { background: radial-gradient(circle, rgba(239, 68, 68, 0.2) 0%, transparent 75%) !important; }
          #blob-1 { background: radial-gradient(circle, #ef4444 0%, transparent 70%) !important; opacity: 0.15 !important; }
          #blob-2 { background: radial-gradient(circle, #facc15 0%, transparent 70%) !important; opacity: 0.1 !important; }
        `}} />
      )}

      <div className="fixed inset-0 pointer-events-none z-[300]">
        {particles.map(p => (
          <div 
            key={p.id}
            className="absolute"
            style={{ 
              left: p.x, 
              top: p.y, 
              width: p.size, 
              height: p.size, 
              backgroundColor: p.color,
              opacity: p.life,
              transform: 'translate(-50%, -50%)',
              imageRendering: 'pixelated',
              boxShadow: `0 0 ${p.isSparkle ? '10px' : '5px'} ${p.color}`,
              filter: p.isSparkle ? 'brightness(3) contrast(1.2)' : 'none'
            }}
          />
