            artist: latest.artist['#text'],
            album: latest.album['#text'],
            image: latest.image[3]['#text'],
            nowPlaying: latest['@attr']?.nowplaying === 'true',
            url: latest.url
          });
        }
      } catch (e) {}
    };
    fetchTrack();
    const interval = setInterval(fetchTrack, 30000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div 
      id="root-container" 
